-- Módulo Propuestas: tablas y catálogo inicial de piezas (152 piezas).
-- Se puede correr más de una vez: no duplica tablas ni piezas.

CREATE TABLE IF NOT EXISTS neura.propuesta_piezas (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  empresa_id uuid NOT NULL,
  seccion text NOT NULL,
  titulo text NOT NULL,
  descripcion text NOT NULL DEFAULT '',
  sort_order integer NOT NULL DEFAULT 0,
  activo boolean NOT NULL DEFAULT true,
  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS propuesta_piezas_empresa_idx ON neura.propuesta_piezas (empresa_id, activo, sort_order);

CREATE TABLE IF NOT EXISTS neura.propuestas (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  empresa_id uuid NOT NULL,
  numero bigint GENERATED BY DEFAULT AS IDENTITY,
  cliente_id uuid,
  cliente_nombre text NOT NULL DEFAULT '',
  titulo text NOT NULL,
  bajada text NOT NULL DEFAULT '',
  piezas jsonb NOT NULL DEFAULT '[]'::jsonb,
  inversion_total numeric(14,0),
  cuota_mensual numeric(14,0),
  condiciones text NOT NULL DEFAULT '',
  archivada boolean NOT NULL DEFAULT false,
  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS propuestas_empresa_idx ON neura.propuestas (empresa_id, archivada, updated_at DESC);

ALTER TABLE neura.propuesta_piezas ENABLE ROW LEVEL SECURITY;
ALTER TABLE neura.propuestas ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON neura.propuesta_piezas TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON neura.propuestas TO service_role;

